def k5_anc_and__ref(n, a):
    qc = QuantumCircuit(n + 1)
    qc.x(n)
    qc.h(n)
    for i in range(0, n - 1):
        if (a >> i) & 1:
            if (a >> (i + 1)) & 1:
                qc.cx(i, n)
    qc.h(n)
    qc.x(n)
    return qc


